insert into public.questions
(exam_category, subject, topic, type, difficulty, body, question_data, options, marks_correct, marks_wrong, explanation, concept_group_id, source_type, source_citation, status)
values
('upsc','History','Music & Dance','statement_based','easy','Consider the following statements regarding Indian classical music and dance:','{"statements": ["Kuchipudi, a classical dance form, originated in Andhra Pradesh.", "Sattriya, associated with the Vaishnava monasteries (Sattras) of Assam, was accorded classical dance status by the Sangeet Natak Akademi in 2000.", "Carnatic music is the classical music tradition of North India, while Hindustani music is the classical tradition of South India."], "closing": "How many of the above statements are correct?"}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: Kuchipudi originated in Andhra Pradesh, and Sattriya, rooted in the Sattras of Assam, was recognised as a classical dance form in 2000. Statement 3 reverses the two traditions: Hindustani music is the classical tradition of North India and Carnatic music that of South India.','art-culture-classical-music-dance-basics','original_pattern_matched','NCERT Fine Arts textbook -- chapter on the performing arts of India.','draft'),
('upsc','History','Music & Dance','statement_based','hard','Consider the following statements regarding the history of Hindustani vocal music:','{"statements": ["Dhrupad received significant royal patronage from Raja Man Singh Tomar of Gwalior in the 15th-16th centuries.", "Khayal is described in detail in Bharata''s Natya Shastra as a principal genre of vocal music.", "Sadarang (Niyamat Khan), a court musician under Aurangzeb, is credited with giving Khayal its refined classical form."], "closing": "How many of the above statements are correct?"}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": true}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: Raja Man Singh Tomar of Gwalior was a major patron of Dhrupad. Statement 2 is an anachronism: Khayal is a medieval genre and is not described in the Natya Shastra, an ancient treatise. Statement 3 swaps the ruler: Sadarang is associated with the court of Muhammad Shah ''Rangila'' in the 18th century, not Aurangzeb, who is remembered for discouraging court music.','art-culture-dhrupad-khayal-history','original_pattern_matched','NCERT Fine Arts textbook -- chapter on Hindustani classical music.','draft'),
('upsc','History','Painting','statement_based','medium','Consider the following statements regarding Pahari and Rajput schools of painting:','{"statements": ["Basohli is regarded as the earliest of the Pahari schools of painting, noted for bold colours and strong lines.", "The Kangra school of Pahari painting flourished under the patronage of Raja Sawant Singh of Kishangarh.", "The ''Bani Thani'' painting is associated with the Bundi school of Rajasthan."], "closing": "How many of the above statements are correct?"}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": true}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Statement 2 swaps the patron: the Kangra school flourished under Raja Sansar Chand of Kangra, while Sawant Singh (Nagari Das) patronised the Kishangarh school. Statement 3 swaps the school: ''Bani Thani'' is the celebrated Kishangarh portrait, attributed to the artist Nihal Chand, not a Bundi work.','art-culture-pahari-rajput-painting-schools','original_pattern_matched','NCERT Fine Arts textbook -- chapter on Pahari and Rajput painting.','draft'),
('upsc','History','Iconography','statement_based','medium','Consider the following statements regarding Jain iconography:','{"statements": ["Jain Tirthankara images are commonly distinguished by distinctive emblems (lanchhanas); the emblem of Rishabhanatha is the bull.", "Mahavira is typically depicted beneath a canopy of serpent hoods.", "The emblem associated with Mahavira is the elephant."], "closing": "How many of the above statements are correct?"}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": true}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: Tirthankaras are identified by lanchhanas, and Rishabhanatha''s is the bull. Statement 2 swaps the Tirthankara: the serpent-hood canopy identifies Parshvanatha, not Mahavira. Statement 3 is also a swap: Mahavira''s emblem is the lion, while the elephant is the emblem of Ajitanatha.','art-culture-jain-iconography-lanchhana','original_pattern_matched','NCERT Fine Arts textbook -- chapter on Jain art and iconography.','draft'),
('upsc','History','Architecture','statement_based','medium','Consider the following statements regarding styles of Indian temple architecture:','{"statements": ["The Nagara style is characterised by a pyramidal vimana and is chiefly associated with South India.", "The Dravida style is characterised by a curvilinear shikhara and is chiefly associated with North India.", "The Vesara style, a blend of Nagara and Dravida features, is found exclusively in Tamil Nadu."], "closing": "How many of the above statements are correct?"}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": true}]'::jsonb,2,0.66,'None of the statements is correct. Statements 1 and 2 swap the defining features and regions: the Nagara style has a curvilinear shikhara and is associated with North India, while the Dravida style has a pyramidal vimana and is associated with South India. Statement 3 misplaces the Vesara style, which developed mainly in Karnataka and the Deccan (for example under the Chalukyas and Hoysalas), not exclusively in Tamil Nadu.','art-culture-temple-styles-nagara-dravida-vesara','original_pattern_matched','NCERT Fine Arts textbook -- chapter on temple architecture.','draft'),
('upsc','History','Medieval','mcq','hard','The ''Diwan-i-Mustakhraj'', a department created to recover arrears of revenue, was established by which Delhi Sultan?','{}'::jsonb,'[{"id": "a", "body": "Balban", "isCorrect": false}, {"id": "b", "body": "Muhammad bin Tughlaq", "isCorrect": false}, {"id": "c", "body": "Firuz Shah Tughlaq", "isCorrect": false}, {"id": "d", "body": "Alauddin Khalji", "isCorrect": true}]'::jsonb,2,0.66,'Alauddin Khalji set up the Diwan-i-Mustakhraj to recover arrears of revenue. The other departments are commonly confused with it: the Diwan-i-Amir-i-Kohi (agriculture) was created by Muhammad bin Tughlaq, the Diwan-i-Khairat (charity) and Diwan-i-Bandagan (slaves) by Firuz Shah Tughlaq, and Balban is associated with reorganising the military department, the Diwan-i-Arz.','medieval-diwan-i-mustakhraj-alauddin','original_pattern_matched','NCERT, Themes in Indian History-II / Old NCERT Medieval India (Satish Chandra) -- chapters on the Khalji and Tughlaq administrations.','draft'),
('upsc','History','Medieval','match_the_following','easy','Match List-I (Mughal emperor) with List-II (Associated work or institution):','{"list_1": ["A. Babur", "B. Akbar", "C. Jahangir", "D. Shah Jahan"], "list_2": ["1. Chain of Justice (Zanjir-i-Adl)", "2. Baburnama", "3. Peacock Throne", "4. Din-i-Ilahi"], "closing": "Select the correct answer using the codes given below:"}'::jsonb,'[{"id": "a", "body": "A-2, B-4, C-1, D-3", "isCorrect": true}, {"id": "b", "body": "A-4, B-1, C-2, D-3", "isCorrect": false}, {"id": "c", "body": "A-1, B-2, C-4, D-3", "isCorrect": false}, {"id": "d", "body": "A-2, B-1, C-3, D-4", "isCorrect": false}]'::jsonb,2,0.66,'The correct pairing is: Babur -- the Baburnama; Akbar -- Din-i-Ilahi; Jahangir -- the Chain of Justice; Shah Jahan -- the Peacock Throne.','medieval-mughal-emperors-works-match','original_pattern_matched','NCERT, Themes in Indian History-II -- chapters on the Mughal emperors.','draft'),
('upsc','History','Medieval','match_the_following','medium','Match List-I (Saint/poet) with List-II (Work):','{"list_1": ["A. Kabir", "B. Tulsidas", "C. Surdas", "D. Malik Muhammad Jayasi"], "list_2": ["1. Ramcharitmanas", "2. Sur Sagar", "3. Padmavat", "4. Bijak"], "closing": "Select the correct answer using the codes given below:"}'::jsonb,'[{"id": "a", "body": "A-2, B-1, C-4, D-3", "isCorrect": false}, {"id": "b", "body": "A-1, B-4, C-2, D-3", "isCorrect": false}, {"id": "c", "body": "A-4, B-1, C-2, D-3", "isCorrect": true}, {"id": "d", "body": "A-2, B-1, C-3, D-4", "isCorrect": false}]'::jsonb,2,0.66,'The correct pairing is: Kabir -- the Bijak; Tulsidas -- the Ramcharitmanas; Surdas -- the Sur Sagar; Malik Muhammad Jayasi -- the Padmavat.','medieval-bhakti-saints-works-match','original_pattern_matched','NCERT, Themes in Indian History-II -- chapter on the Bhakti and Sufi traditions.','draft'),
('upsc','History','Modern','match_the_following','hard','Match List-I (Session of the Indian National Congress) with List-II (Presiding officer):','{"list_1": ["A. Surat (1907)", "B. Lucknow (1916)", "C. Nagpur (1920)", "D. Karachi (1931)"], "list_2": ["1. Vallabhbhai Patel", "2. C. Vijayaraghavachariar", "3. Rash Behari Ghosh", "4. Ambika Charan Mazumdar"], "closing": "Select the correct answer using the codes given below:"}'::jsonb,'[{"id": "a", "body": "A-3, B-4, C-2, D-1", "isCorrect": true}, {"id": "b", "body": "A-4, B-3, C-2, D-1", "isCorrect": false}, {"id": "c", "body": "A-3, B-4, C-1, D-2", "isCorrect": false}, {"id": "d", "body": "A-1, B-3, C-2, D-4", "isCorrect": false}]'::jsonb,2,0.66,'The correct pairing is: the Surat session (1907) was presided over by Rash Behari Ghosh; Lucknow (1916) by Ambika Charan Mazumdar; Nagpur (1920) by C. Vijayaraghavachariar; and Karachi (1931) by Vallabhbhai Patel.','modern-inc-sessions-presidents-match','original_pattern_matched','NCERT/Bipan Chandra, India''s Struggle for Independence -- chronology of Congress sessions.','draft'),
('upsc','History','Ancient','match_the_following','hard','Match List-I (Ruler) with List-II (Title/epithet associated with them):','{"list_1": ["A. Ashoka", "B. Samudragupta", "C. Chandragupta II", "D. Kanishka"], "list_2": ["1. Kaviraja", "2. Devanampiya Piyadasi", "3. Devaputra", "4. Vikramaditya"], "closing": "Select the correct answer using the codes given below:"}'::jsonb,'[{"id": "a", "body": "A-3, B-1, C-2, D-4", "isCorrect": false}, {"id": "b", "body": "A-2, B-1, C-4, D-3", "isCorrect": true}, {"id": "c", "body": "A-1, B-3, C-4, D-2", "isCorrect": false}, {"id": "d", "body": "A-3, B-2, C-4, D-1", "isCorrect": false}]'::jsonb,2,0.66,'The correct pairing is: Ashoka -- Devanampiya Piyadasi (as in his edicts); Samudragupta -- Kaviraja (as in the Allahabad Prashasti); Chandragupta II -- Vikramaditya; Kanishka -- Devaputra, a title used by the Kushan kings.','ancient-rulers-titles-match','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapters on the Mauryas, Kushans and Guptas.','draft'),
('upsc','History','Medieval','match_the_following','hard','Match List-I (Medieval work) with List-II (Author):','{"list_1": ["A. Tabaqat-i-Nasiri", "B. Fatawa-i-Jahandari", "C. Khazain-ul-Futuh", "D. Tuzuk-i-Jahangiri"], "list_2": ["1. Ziauddin Barani", "2. Jahangir", "3. Minhaj-us-Siraj", "4. Amir Khusrau"], "closing": "Select the correct answer using the codes given below:"}'::jsonb,'[{"id": "a", "body": "A-4, B-3, C-1, D-2", "isCorrect": false}, {"id": "b", "body": "A-2, B-1, C-3, D-4", "isCorrect": false}, {"id": "c", "body": "A-3, B-1, C-4, D-2", "isCorrect": true}, {"id": "d", "body": "A-2, B-1, C-4, D-3", "isCorrect": false}]'::jsonb,2,0.66,'The correct pairing is: the Tabaqat-i-Nasiri was written by Minhaj-us-Siraj; the Fatawa-i-Jahandari by Ziauddin Barani; the Khazain-ul-Futuh by Amir Khusrau; and the Tuzuk-i-Jahangiri is the memoir of Emperor Jahangir.','medieval-chronicles-authors-match','original_pattern_matched','NCERT, Themes in Indian History-II / Old NCERT Medieval India (Satish Chandra) -- chapters on medieval sources.','draft')
